// Тикет #6a86f7d9 (+#6a86f7e6). Опора: реджект 27.09, ответ 28.09; строки утверждены 24.09; Figma 454:4808 (окно), 457:12061 (предпросмотр).
// AC-02: предпросмотр своего окна (текст сообщения) и «ביטול».
// ОБНОВЛЕНО 13.10.2026 — #403c0b3d (403c0b3d68a0731743731d65) עבר QA, iPhone TestFlight 1.0.0 (19), user1 («30 תפילות: הושג»);
// скрины 403c0b3d-ios-b19-achievement-window.png, -share-preview.png, -share-sheet.png:
//  AC-02b «שיתוף ההישג» → превью → «המשך לשיתוף» → системное окно шаринга (закрыть свайпом вниз, НЕ отправлять) → «סגירה» →
//        вкладки «בית», «תהילים», «המסע שלי», «ברכות» переключаются; «מפת השפעה» не меняется («N אנשים» до и после);
//  AC-02c «ביטול» → окно достижения остаётся → «סגירה» → вкладки работают. Также F-95 #6a86f7e8 AC4 (шаринг достижения).
import { expect } from '@wdio/globals';
import { byText, byTextContains, byLabel, tapText, tapLabel, expectVisibleText, expectTextContains, scrollToText } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';
import { expectSharePreview, waitShareSheet, dismissShareSheet, expectTabsSwitch, impactMapCount, switchTabAndCheck } from '../_lib/app-1310.ts';

const MESSAGE = 'השגתי את ההישג «30 תפילות» באפליקציית אור הגאולה. מצטרפים להתחזק בתפילה יחד?';

/** «המסע שלי» → окно достижения «30 תפילות». */
async function openAchievement30() {
  await toHome();
  await switchTabAndCheck('המסע שלי');
  const w = await byTextContains('עלית דרגה');
  if (await w.waitForDisplayed({ timeout: 1500 }).then(() => true, () => false)) await tapText('סגירה');
  await scrollToText('הישגים');
  await scrollToText('100 תפילות');
  await tapLabel('30 תפילות: הושג');
  await expectVisibleText('שיתוף ההישג');
}

describe('Достижения', () => {
  afterEach(async () => { await toHome(); });

  it('AC-02 Окно полученного достижения — строка ободрения, «חזרה למסך ראשי», предпросмотр шеринга с текстом #6a86f7d9 @prod-safe', async () => {
    // 1. «המסע שלי» → «30 תפילות: הושג».
    await goTab('המסע שלי');
    await (await byText('המסע שלי')).waitForDisplayed({ timeout: 20000 });
    const w = await byTextContains('עלית דרגה');
    if (await w.waitForDisplayed({ timeout: 1500 }).then(() => true, () => false)) await tapText('סגירה');
    await scrollToText('הישגים');
    await scrollToText('100 תפילות');
    await tapLabel('30 תפילות: הושג');

    // Окно: заголовок, строка ободрения, 3 кнопки.
    await expectTextContains('שלושים תפילות — התפילה הופכת לחלק מהיום שלך');
    await expectVisibleText('חזרה למסך ראשי');
    await expectVisibleText('שיתוף ההישג');
    await expect(byLabel('סגירה')).toBeDisplayed();

    // 2. «שיתוף ההישג» → предпросмотр: пояснение, текст сообщения, «ביטול», «המשך לשיתוף».
    await tapText('שיתוף ההישג');
    await expectTextContains('זו ההודעה שתישלח, בלי שום פרט נוסף:');
    await expectTextContains(MESSAGE);
    await expectVisibleText('המשך לשיתוף');
    await tapText('ביטול');
    await expect(byText('המשך לשיתוף')).not.toBeDisplayed();

    // 3. Закрыть окно «סגירה» (если после «ביטול» оно ещё открыто).
    const close = await byLabel('סגירה');
    if (await close.isDisplayed().catch(() => false)) await close.click();
    await expect(byText('חזרה למסך ראשי')).not.toBeDisplayed();

    // 4. «פרופיל אישי» → «אודות»: имя приложения «אור הגאולה».
    await goTab('המסע שלי');
    await tapLabel('מעבר לפרטים שלי');
    await expectVisibleText('פרופיל אישי');
    await scrollToText('אודות', 12);
    await scrollToText('אפליקציית "אור הגאולה"', 6);
  });

  it('AC-02b «שיתוף ההישג» → «המשך לשיתוף» → системное окно (закрыто без отправки) → «סגירה» → вкладки работают; «מפת השפעה» без изменений #403c0b3d #6a86f7e8 @prod-safe', async () => {
    const before = await impactMapCount();
    await openAchievement30();
    await tapText('שיתוף ההישג');
    await expectSharePreview(MESSAGE);
    await tapText('המשך לשיתוף');
    await waitShareSheet();
    await dismissShareSheet();
    const close = await byLabel('סגירה');
    if (await close.isDisplayed().catch(() => false)) await close.click();
    await expect(byText('שיתוף ההישג')).not.toBeDisplayed();
    await expectTabsSwitch();
    expect(await impactMapCount()).toBe(before);
  });

  it('AC-02c «שיתוף ההישג» → «ביטול»: окно достижения остаётся → «סגירה» → вкладки работают; карта без изменений #403c0b3d @prod-safe', async () => {
    const before = await impactMapCount();
    await openAchievement30();
    await tapText('שיתוף ההישג');
    await expectSharePreview(MESSAGE);
    await tapText('ביטול');
    await expect(byText('המשך לשיתוף')).not.toBeDisplayed();
    await expectVisibleText('שיתוף ההישג');            // окно достижения на месте
    await tapLabel('סגירה');
    await expect(byText('שיתוף ההישג')).not.toBeDisplayed();
    await expectTabsSwitch();
    expect(await impactMapCount()).toBe(before);
  });
});
